/**
 * 判断指定的字符串是ipv4
 * @param str
 * @example
 * console.log(isIPv4('10.120.78.40'));
 * // ==> true
 * console.log(isIPv4('0.0.0.12'));
 * // ==> true
 * console.log(isIPv4('266.120.78.40'));
 * // ==> false
 * console.log(isIPv4('dd.120.78.40'));
 * // ==> false
 */
export default function isIPv4(ip: string): boolean;
/**
 * 判断指定的字符串是ipv6
 * @param str
 * @example
 * console.log(isIPv4('2001:ab8:1234:0000:0000:0000:0000:0000'));
 * // ==> true
 * console.log(isIPv4('1:ab::3'));
 * // ==> true
 * console.log(isIPv4('2001:0ab8:0z00:0023:0008:0800:200C:417a'));
 * // ==> false
 * console.log(isIPv4('2001:ab8::23::800:192.1.0.0'));
 * // ==> false
 */
export declare function isIPv6(ip: string): boolean;
/**
 * 校验ipv6是否合法，并给合法的ipv6添加[]，不合法的返回空字符串
 * @param str
 * @example
 * console.log(isIPv4('2001:ab8:1234:0000:0000:0000:0000:0000'));
 * // ==> [2001:ab8:1234:0000:0000:0000:0000:0000]
 */
export declare function addBracketsToIPv6(ipv6: string): string;
/**
 * 压缩IPv6地址：支持纯IPv6和内嵌IPv4格式（如::ffff:192.168.1.1）
 * @param ip 未压缩的IPv6地址
 * @returns 压缩后的IPv6地址
 * @example
 * compressIPv6("2001:0db8:0000:0000:0000:ffff:192.168.254.1")
 * // 返回 "2001:db8::ffff:c0a8:fe01"
 * compressIPv6("0000:0000:0000:0000:0000:0000:192.168.1.1")
 * // 返回 "::c0a8:101"
 */
export declare function compressIPv6(ip: string): string;
